{ "hypotheses": [
  {
    "root_cause": "Failed planning-api rollout / zero ready replicas",
    "mechanism": "The planning-api Deployment rolled out pods that never became ready (crash-loop or readiness failure), leaving zero ready pods behind the Service.",
    "statement": "Grid-operator could not reach planning-api because the planning-api Service had no backend endpoints."
  },
  {
    "root_cause": "Kubernetes planning-api Service selector mismatch / endpoint loss",
    "mechanism": "The planning-api Service selector was changed or misconfigured so it no longer matched running planning-api pods, causing an empty endpoint set.",
    "statement": "DNS resolution of the Service would have succeeded, but there were no reachable planning-api backends."
  },
  {
    "root_cause": "grid-operator client-side service discovery failure",
    "mechanism": "The grid-operator pod held a stale planning-api address, wrong port, or cached DNS entry, so its connection attempts failed regardless of planning-api health.",
    "statement": "The fault originates in the consumer rather than in planning-api."
  },
  {
    "root_cause": "PostgreSQL dependency outage",
    "mechanism": "PostgreSQL became unavailable or too slow, causing planning-api readiness probes to fail and its pods to be removed from the Service.",
    "statement": "A broken critical upstream dependency made planning-api unreachable even if planning-api pods were still running."
  },
  {
    "root_cause": "Network policy / CNI traffic block",
    "mechanism": "A Kubernetes network policy or CNI fault blocked traffic from grid-operator to planning-api, resulting in connection timeouts.",
    "statement": "The network path between grid-operator and planning-api was severed, so planning-api may have been healthy but unreachable."
  }
] }
